 $idKategori=filter_input(INPUT_POST,'id_kategori',FILTER_VALIDATE_INT);$nama=trim($_POST['nama_produk']??'');$harga=filter_input(INPUT_POST,'harga',FILTER_VALIDATE_INT);$stok=filter_input(INPUT_POST,'stok',FILTER_VALIDATE_INT);
 if(!$idKategori||$nama===''||mb_strlen($nama)>150||$harga===false||$harga===null||$harga<0||$stok===false||$stok===null||$stok<0)$error='Lengkapi data dengan benar. Harga dan stok harus berupa angka tidak negatif.';
 if($error===''){$cek=$conn->prepare('SELECT id_kategori FROM kategori WHERE id_kategori=?');$cek->bind_param('i',$idKategori);$cek->execute();$ok=$cek->get_result()->fetch_assoc();$cek->close();if(!$ok)$error='Kategori yang dipilih tidak ditemukan.';}
 $foto=$product['foto'];if($error===''&&isset($_FILES['foto'])&&$_FILES['foto']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['foto'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];$mime=$f['tmp_name']&&is_uploaded_file($f['tmp_name'])?mime_content_type($f['tmp_name']):'';if($f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024||!isset($allowed[$mime]))$error='Foto harus JPG, PNG, WEBP, atau GIF dan maksimal 5 MB.';else{$newFoto=bin2hex(random_bytes(12)).'.'.$allowed[$mime];$dir=__DIR__.'/gambar';if(!is_dir($dir))mkdir($dir,0755,true);if(move_uploaded_file($f['tmp_name'],$dir.'/'.$newFoto))$foto=$newFoto;else$error='Gagal mengunggah foto.';}}
 if($error===''){$upd=$conn->prepare('UPDATE produk SET id_kategori=?,nama_produk=?,harga=?,stok=?,foto=? WHERE id_produk=?');if(!$upd)$error='Gagal menyiapkan perubahan produk.';else{$upd->bind_param('isiisi',$idKategori,$nama,$harga,$stok,$foto,$id);if($upd->execute()){$upd->close();if(!empty($product['foto'])&&$foto!==$product['foto']&&is_file(__DIR__.'/gambar/'.$product['foto']))@unlink(__DIR__.'/gambar/'.$product['foto']);$_SESSION['flash_produk']='Produk berhasil diedit!';header('Location: Tproduk.php');exit;}$error='Produk gagal diperbarui: '.$upd->error;$upd->close();}}
 $product=array_merge($product,['id_kategori'=>$idKategori,'nama_produk'=>$nama,'harga'=>$harga,'stok'=>$stok,'foto'=>$foto]);
